  await setNight(1); const night = await shot(NO_SHOTS || BASELINE ? null : 'citynight-night');
  if (BASELINE) {
    writeFileSync(base('day'), Buffer.from(day, 'base64')); writeFileSync(base('night'), Buffer.from(night, 'base64'));
    console.log('Đã lưu mốc chuẩn ngày/đêm');
  } else {
    if (!existsSync(base('day'))) throw new Error('Thiếu mốc chuẩn: chạy --baseline trên bản chưa sửa');
    const d = await sample(day, ALL, readFileSync(base('day')).toString('base64'));
    check(d.diff < 3, `dayDiff: ban ngày chênh ${d.diff.toFixed(2)}/255 (cần < 3)`);
    const t = await sample(night, TOP);
    console.log('đêm:', JSON.stringify(t));
    const colored = t.warm + t.cool + t.led;   // chỉ so giữa các nhóm màu đèn: sao trời, cầu, địa danh trắng không thuộc phạm vi
    check(colored > 0 && t.warm / colored >= 0.6, `warmDominant: vàng ấm ${(100 * t.warm / colored).toFixed(1)} % số pixel có màu đèn (cần ≥ 60 %)`);
    check(t.cool / t.n >= 0.001, `coolSeen: xanh ${(100 * t.cool / t.n).toFixed(3)} % (cần ≥ 0,1 %)`);
    check(t.led / t.n >= 0.0005, `ledSeen: LED ${(100 * t.led / t.n).toFixed(3)} % (cần ≥ 0,05 %)`);
    const keys = await page.evaluate(() => {
      const a = window.__app; let lm = null, city = null;
      a.scene.traverse((o) => { if (o.name === 'rf-landmarks') lm = o.material.customProgramCacheKey(); if (!city && o.isLOD && o.levels[0].object.isInstancedMesh) city = o.levels[0].object.material.customProgramCacheKey(); });
      return { lm, city };
    });
    check(keys.lm === 'windows', `landmark: khóa địa danh "${keys.lm}"`);
    check(keys.city === 'windows-city', `landmark: khóa nhà khu phố "${keys.city}"`);
    const WATER = [0, 0.6, 1, 1], SHORE = [0, 0.58, 1, 0.85];
    const w = await sample(night, SHORE), lit = w.warm + w.cool + w.led;
    console.log('nước gần bờ:', JSON.stringify(w));
    check(lit >= 2 * STREAK_REF, `streak: ${lit} pixel màu đèn trên sông (cần ≥ 2 lần mức chưa có vệt, ${STREAK_REF})`);
    await setNight(0.5); const m = await sample(await shot(null), ALL); await setNight(0); const m0 = await sample(await shot(null), ALL); await setNight(1); const m1 = await sample(await shot(null), ALL);
    console.log('dusk:', m0.mean.toFixed(1), m.mean.toFixed(1), m1.mean.toFixed(1), 'sáng', m0.bright, m.bright, m1.bright);
    check(m.mean <= DUSK_REF + 5, `dusk: độ sáng lúc 0,5 = ${m.mean.toFixed(1)} (cần ≤ ${DUSK_REF + 5}, mức có sẵn do bloom bật sớm)`);
    await setNight(0.5); const r5 = await sample(await shot(null), WATER); await setNight(0.75); const r75 = await sample(await shot(null), WATER); await setNight(1);
    console.log('nước lúc 0,5 / 0,75:', r5.mean.toFixed(1), r75.mean.toFixed(1));
    check(r75.mean <= r5.mean + 3, `duskWater: mặt sông lúc 0,75 = ${r75.mean.toFixed(1)}, không được sáng hơn lúc 0,5 = ${r5.mean.toFixed(1)}`);
    const flat = await page.evaluate(() => { const { renderer } = window.__app, gl = renderer.getContext(), p = renderer.info.programs.find((x) => x.cacheKey.includes('windows-city')); return p ? gl.getShaderSource(p.fragmentShader) : ''; });
    check(/flat\s+varying\s+vec2\s+vBId/.test(flat) && /flat\s+varying\s+vec3\s+vBSize/.test(flat), 'flatId: định danh từng tòa phải là varying flat (không nội suy)');
    await page.evaluate(() => { window.__app.reflectState.every = 0; }); await frames(page, 3);
    const nm = await sample(await shot(null), WATER);
    check(nm.std <= NOMIRROR_REF + 3, `noMirror: độ lệch chuẩn mặt nước ${nm.std.toFixed(1)} (cần ≤ ${NOMIRROR_REF + 3})`);
    await page.evaluate(() => { window.__app.reflectState.every = 1; }); await frames(page, 2);
    await aim([-500, 120, -1700], [-500, 0, -1699]);
    const c = await sample(await shot(null), [0.45, 0.45, 0.55, 0.55]);
    check(c.warm === 0, `corridor: hành lang Hầm có ${c.warm} pixel đèn (cần 0)`);
  }

